def check(output, ctx):
    try:
        import re, sqlglot
        q = ctx['question'].lower()
        if not re.search(r'\b(ascending|increasing)\b', q): return True
        if re.search(r'\b(descending|decreasing|reverse|desc|top)\b', q): return True
        tree = sqlglot.parse_one(extract_sql(output), read='sqlite')
        if tree.args.get('limit'): return True
        o = tree.args.get('order')
        if not o: return True
        return not any(e.args.get('desc') for e in o.expressions)
    except Exception:
        return True

